/* CastFltPsgMapper.retrieveFltPsgHourList */ SELECT SUBSTR(X.HM, 1, 2) AS HOUR, COUNT(*) AS FLT_CNT, NVL(SUM(X.PSG_CNT), 0) AS PSG_CNT FROM ( SELECT A.TMNL_ID, A.DOM_INTL_SE_CD, NVL(A.PREDC_HM, A.SCHDL_HM) AS HM, GREATEST( NVL(TO_NUMBER(TRIM(A.RSVT_BDPSG_CNT)), 0) - NVL(TO_NUMBER(TRIM(A.RSVT_TRNS_BDPSG_CNT)), 0), 0 ) AS PSG_CNT, ROW_NUMBER() OVER ( PARTITION BY A.ARR_DEP_SE_CD, A.FLTNM, A.GD_SE_YMD, A.SCHDL_HM ORDER BY A.RSVT_BDPSG_CNT DESC NULLS LAST ) AS RN FROM GOOWN.TN_GO_GD_DATA A WHERE 1 = 1 AND A.GD_SE_YMD = #{ymd} AND A.ARR_DEP_SE_CD = 'D' AND A.TMNL_ID IN ('P01', 'P02', 'P03') AND A.CSHR_STTS_CD != 'SL' AND A.DLY_RSN_CD NOT IN ('2', '3') AND A.ARCFT_USE_SE_CD = '0' AND A.GD_FLT_PRPS_CD IN ('00', '05') AND A.PSG_CGO_SE_CD = 'Y' AND A.FRY_YN = 'N' AND A.LCRFT_YN = 'N' AND A.SCHDL_HM IS NOT NULL ) X WHERE X.RN = 1 AND X.DOM_INTL_SE_CD != 'D'
AND X.TMNL_ID IN (#{item})
GROUP BY SUBSTR(X.HM, 1, 2) ORDER BY HOUR

/* CastFltPsgMapper.retrieveUserFltPsg */
SELECT
    NVL(A.AJMT_RT, 0) AS AJMT_RT
FROM PMOWN.TN_PM_SMLT_USER_FLT_PSG_AJMT A
WHERE 1 = 1
AND A.OWNER_USER_ID = #{loginUserId}
AND A.EXCN_YMD = #{ymd}
AND A.TMNL_ID = #{fcltTmnlId}

mapper.update:
/* CastFltPsgMapper.updateUserFltPsg */
UPDATE PMOWN.TN_PM_SMLT_USER_FLT_PSG_AJMT
SET AJMT_TYPE_CD = 'RATIO',
    AJMT_RT = #{ajmtRt},
    LAST_MDFR_ID = #{loginUserId},
    LAST_MDFR_IP_ADDR = #{loginIpAddr},
    LAST_MDFCN_DT = CURRENT_TIMESTAMP
WHERE 1 = 1
AND OWNER_USER_ID = #{loginUserId}
AND EXCN_YMD = #{ymd}
AND TMNL_ID = #{fcltTmnlId}
